    public static function findById(string $studyId): ?array
    {
        $all = static::getAllPublications();
        return $all[$studyId] ?? null;
    }

    public static function getTopImpactPublications(int $limit = 20): array
    {
        $all = static::getAllPublications();
        uasort($all, fn($a, $b) => $b['impact_factor'] <=> $a['impact_factor']);
        return array_slice($all, 0, $limit);
    }

    public static function getTotalStudiesCount(): int
    {
        return count(static::getAllPublications());
    }
}